import itertools

def get_autocorr(seq, k):
    return sum(seq[i] * seq[i+k] for i in range(len(seq)-k))

def solve():
    for seq in itertools.product([-1, 1], repeat=12):
        energy = sum(get_autocorr(seq, k)**2 for k in range(1, 12))
        if energy <= 25:
            print(f"Found: {list(seq)} with energy {energy}")
            return list(seq)
    print("UNSATISFIABLE")

solve()
